/** The strongest native target supported by the existing focus mechanism. */
export type C9pOpenTarget = 'terminal' | 'project' | 'application' | string;

/**
 * `provider.opencode.connect` params: the OpenCode server detection
 * reads. An empty `url` disconnects. The engine keeps the credentials in
 * memory only and never returns them.
 */
export interface C9pOpencodeConnectParams {
  password?: string | null;
  url: string;
  username?: string;
}

export interface C9pOpencodeStatus {
  connected: boolean;
  error: string | null;
  sessionCount: number;
  url: string;
}

/** `provider.opencode.status` params. There are none yet. */
export type C9pOpencodeStatusParams = Record<string, unknown>;

/**
 * A window of a list: at most `limit` items from `offset`.
 *
 * A page also stops before its items would pass a byte budget (half of
 * `limits.maxFrame`), so it can hold fewer than `limit` items. A page from
 * an `offset` before the end always holds at least one item, so
 * `nextOffset` always moves forward. An item too large for the budget on
 * its own comes alone, with its large text replaced by a short note and
 * `truncated: true`.
 */
export interface C9pPageParams {
  /**
   * At most this many items. Default 200; a value over 1000 is treated
   * as 1000; 0 is `bad_request`.
   */
  limit?: number | null;
  offset?: number;
}

/** `ping` params. There are none. */
export type C9pPingParams = Record<string, unknown>;

/** `ping` result: the engine's clock. */
export interface C9pPingResult {
  /** Unix milliseconds. */
  ts: number;
}

/**
 * A `progress` frame: how far a read for request `id` has got. Sent only
 * to a connection that asked for the `conversation.progress` capability,
 * before that request's response. Never stored; a slow client may miss
 * some.
 */
export interface C9pProgressFrame {
  bytesRead: number;
  bytesTotal: number;
  /** The `id` of the request it reports on. */
  id: string | null;
  type: C9pProgressType;
  v: number;
}

/** The `type` of a progress frame. */
export type C9pProgressType = 'progress' | string;

export interface C9pProjectCost {
  project: string;
  projectName: string;
  sessions: C9pSessionCostRecord[];
  totalCost: number;
}

/** All memory files for a single project */
export interface C9pProjectMemory {
  /** Memory files found in this project */
  files: C9pMemoryFile[];
  /** Absolute path to the memory directory (for "Reveal in Finder") */
  memoryDirPath: string;
  /** Human-readable project name (last path segment, e.g. "c9watch") */
  projectName: string;
  /** Decoded full project path (e.g. "/Users/liminchen/Documents/GitHub/c9watch") */
  projectPath: string;
  /** Provider that owns this memory group. Older payloads default to Claude Code. */
  provider: C9pSessionProvider;
}

/**
 * A request frame. Every field is optional on the wire, so that a frame
 * with a missing field still gets an error that echoes its `id`.
 */
export interface C9pRequest {
  id?: string | null;
  idem?: string | null;
  method?: string | null;
  params?: unknown;
  v?: number | null;
}

/** A response frame: `ok:true` with `result`, or `ok:false` with `error`. */
export interface C9pResponse {
  error?: C9pErrorBody | null;
  id?: string | null;
  ok: boolean;
  result?: unknown;
  /** Cursor of the event this write produced (from M2). */
  seq?: string | null;
  v: number;
}

/** `session.away` params: one request per session. */
export interface C9pSessionAwayParams {
  requests?: C9pAwayRequest[];
}

/**
 * `session.away` result: what each session did after its `sinceMs`,
 * keyed by session key. A session without an index (not Claude Code, or
 * not seen by a detection tick yet) is absent.
 */
export interface C9pSessionAwayResult {
  activity: Record<string, C9pAwayActivity>;
}

/** A single session's cost record (stored in cache). */
export interface C9pSessionCostRecord {
  agentKind?: string | null;
  cachedInputTokens: number;
  cost: number;
  costAvailable: boolean;
  date: string;
  inputTokens: number;
  model: string;
  outputTokens: number;
  project: string;
  projectName: string;
  provider: string;
  reasoningOutputTokens: number;
  sessionId: string;
  sessionName: string;
  surface?: string | null;
  timestamp: string;
  totalTokens: number;
}

/** `session.gone` data. */
export interface C9pSessionGoneEvent {
  /** The provider session id. */
  id: string;
  /** `<provider>:<session id>`. */
  sessionKey: string;
}

export type C9pSessionKind = 'interactive' | 'background' | 'unknown' | string;

/**
 * `session.list` params. There are none yet; the engine ignores any it
 * gets.
 */
export type C9pSessionListParams = Record<string, unknown>;

/**
 * `session.list` result: the agents whose session detection sees now
 * (`goneAt` is `null`), in creation order.
 */
export interface C9pSessionListResult {
  sessions: C9pAgentRow[];
}

export type C9pSessionProvider = 'claudeCode' | 'codex' | 'cursor' | 'pi' | 'opencode' | string;

/** `session.rename` params: set a Claude Code session's custom title. */
export interface C9pSessionRenameParams {
  newName: string;
  /**
   * Only `claudeCode`. Without it, an id that another provider also
   * has is refused.
   */
  provider?: C9pSessionProvider | null;
  /** The provider session id. */
  sessionId: string;
}

/** Represents the current status of a Claude Code session */
export type C9pSessionStatus =
  /** Claude is actively executing tools or thinking */
  | 'Working'
  /** Waiting for user attention (tool approval, question, etc.) */
  | 'NeedsAttention'
  /** Idle, ready for next prompt */
  | 'WaitingForInput'
  /** Session starting up or no recent activity */
  | 'Connecting'
  | string;

/**
 * `session.stop` params: stop an observed Claude Code session with
 * SIGTERM. The pid comes from the engine's own detection.
 */
export interface C9pSessionStopParams {
  /** When given, detection must still see the session as this pid. */
  pid?: number | null;
  /** `<provider>:<session id>`. */
  sessionKey: string;
}

export type C9pSessionSurface = 'claudeCode' | 'app' | 'cli' | 'exec' | 'integration' | 'cursor' | 'unknown' | string;

/** `session.tasks` params. */
export interface C9pSessionTasksParams {
  /** The raw Claude Code session id. */
  sessionId: string;
}

/**
 * `session.tasks` result: the session's TodoWrite tasks as Claude Code
 * wrote them, sorted by numeric `id`.
 */
export interface C9pSessionTasksResult {
  tasks: unknown[];
}

/** Combined session information */
export interface C9pSessionView {
  agentKind: C9pAgentKind;
  agentNickname?: string | null;
  agentPath?: string | null;
  agentRole?: string | null;
  /** Claude Code's auto-generated title (`ai-title` in the session JSONL). */
  aiTitle?: string | null;
  canOpen: boolean;
  canRename: boolean;
  canStop: boolean;
  /** Codex's current UI thread name from ~/.codex/session_index.jsonl. */
  codexTitle?: string | null;
  /** Cursor's current UI composer name from state.vscdb. */
  cursorTitle?: string | null;
  customTitle: string | null;
  /**
   * Raw `entrypoint` from `~/.claude/sessions/<pid>.json` (e.g. "cli", "sdk-cli",
   * "claude-vscode", "mcp", "remote_desktop"...). Only the CLI backend populates
   * this; `None` covers the legacy backend and non-Claude-Code providers.
   */
  entrypoint?: string | null;
  firstPrompt: string;
  gitBranch: string | null;
  id: string;
  internalKind?: string | null;
  /**
   * Interactive vs. background-pinned (`claude agents --json`'s `kind`).
   * Providers other than Claude Code always report `Interactive`.
   */
  kind: C9pSessionKind;
  /** One-line, tag-free preview of the last assistant text. */
  lastAssistantMessage?: string | null;
  latestMessage: string;
  messageCount: number;
  modified: string;
  /**
   * User-set name from `claude agents` (Ctrl+T background-pinned sessions).
   * Only populated by the CLI backend; legacy backend leaves this None.
   */
  officialName?: string | null;
  /** Native target guarantee; absent means no verified exact native target. */
  openTarget?: C9pOpenTarget | null;
  parentThreadId?: string | null;
  /** The input/arguments of the pending tool (when status is NeedsPermission) */
  pendingToolInput?: unknown;
  pendingToolName: string | null;
  pid: number;
  projectPath: string;
  provider: C9pSessionProvider;
  rootSessionId?: string | null;
  /** Provider-scoped identity used by frontend selection and backend maps. */
  sessionKey: string;
  sessionName: string;
  /** Health of the source observation, independent of the session status. */
  sourceHealth?: C9pSourceHealth | null;
  /**
   * Session start time in ms since epoch (from `claude agents --json`).
   * Only populated by the CLI backend; legacy backend leaves this None.
   */
  startedAtMs?: number | null;
  status: C9pSessionStatus;
  summary: string | null;
  surface: C9pSessionSurface;
  /** What the session needs from the user (tool name only, never arguments). */
  waitingFor?: C9pWaitingFor | null;
  /**
   * Session ID of the PM that spawned this session (if it's a c9watch worker).
   * Set by the workers overlay from `~/.claude/c9watch/workers/*\/meta.json`
   * (`session::workers`), after detection.
   */
  workerOf?: string | null;
}

/**
 * `session.views` params. There are none yet; the engine ignores any it
 * gets.
 */
export type C9pSessionViewsParams = Record<string, unknown>;

/**
 * `session.views` result: the sessions of the last detection tick, as the
 * GUI shows them, in detection order, and the cursor they are consistent
 * with. Subscribing to `session.*` with `since` = `cursor` continues with
 * no gap: `session.view` carries a new or changed session in full,
 * `session.gone` (`SessionGoneEvent`) one that ended.
 */
export interface C9pSessionViewsResult {
  cursor: string;
  sessions: C9pSessionView[];
}

/**
 * `snapshot.get` params. There are none yet; the engine ignores any it
 * gets.
 */
export type C9pSnapshotParams = Record<string, unknown>;

/**
 * `snapshot.get` result: the state and the cursor it is consistent with.
 * Subscribing with `since` = `cursor` continues with no gap.
 */
export interface C9pSnapshotResult {
  agents: C9pAgentRow[];
  cursor: string;
  machineId: string;
}

/**
 * Health of the source observation used to produce a session card.
 *
 * This is deliberately separate from `SessionStatus`: a session can be
 * waiting for input while its source is fresh, partial, or unavailable.
 */
export type C9pSourceHealth = 'fresh' | 'stale' | 'partial' | 'unavailable' | 'unknown' | string;

/** A subagent invocation found in a parent session's JSONL. */
export interface C9pSubagentInfo {
  /** `subagent_type` from the Agent tool input (e.g. "general-purpose", "Explore"). */
  agentType: string;
  /** ISO-8601 timestamp when the tool_result was recorded (None if still running). */
  completedAt: string | null;
  /** Short description of the task (`description` field of Agent tool input). */
  description: string;
  /** The Agent tool's `tool_use_id` — unique within the parent session. */
  id: string;
  /** Parent session's UUID. */
  parentSessionId: string;
  /** ISO-8601 timestamp when the tool_use was recorded. */
  startedAt: string;
  /** Running or Completed. */
  status: C9pSubagentStatus;
}

/**
 * `subagent.list` params: the raw Claude Code session ids the caller
 * shows (not session keys).
 */
export interface C9pSubagentListParams {
  sessionIds?: string[];
}

/** `subagent.list` result: parent session id → its subagent invocations. */
export interface C9pSubagentListResult {
  subagents: Record<string, C9pSubagentInfo[]>;
}

/** Status of a detected subagent. */
export type C9pSubagentStatus = 'running' | 'completed' | string;

/**
 * Full transcript of a single subagent invocation — the prompt (Agent tool
 * input), the final result text, and usage stats when available.
 */
export interface C9pSubagentTranscript {
  /** Internal agent id from `toolUseResult.agentId` (CC sub-agent handle). */
  agentId: string | null;
  agentType: string;
  completedAt: string | null;
  description: string;
  durationMs: number | null;
  id: string;
  parentSessionId: string;
  /** Prompt sent to the subagent (from the Agent tool_use input). */
  prompt: string;
  /**
   * Final result text from the subagent, if completed. Concatenation of
   * text blocks in the matching tool_result content array, preferring
   * `toolUseResult.content[].text` when present.
   */
  result: string | null;
  startedAt: string;
  status: C9pSubagentStatus;
  toolUses: number | null;
  totalTokens: number | null;
}

/** `subagent.transcript` params. */
export interface C9pSubagentTranscriptParams {
  parentSessionId: string;
  /** The Agent tool's `tool_use_id`. */
  subagentId: string;
}

/** `events.subscribe` params (A:218). Empty filters match everything. */
export interface C9pSubscribeParams {
  /**
   * The last cursor the client has seen. Without it, the stream starts at
   * the current head.
   */
  since?: string | null;
  /** Exact subjects. */
  subjects?: string[];
  /** Exact topics, or a prefix ending in `.*` (`agent.*`). */
  topics?: string[];
}

/**
 * `events.subscribe` result. Event frames follow it on the same
 * connection until the connection closes, or until an error frame with
 * the subscribe request's `id` (`cursor_expired` when the subscriber fell
 * behind retention).
 */
export interface C9pSubscribeResult {
  /** Where the stream starts: events after this cursor follow. */
  cursor: string;
}

export interface C9pSubscriptionUsage {
  message: string | null;
  name: string;
  plan: string | null;
  provider: string;
  updatedAt: number | null;
  windows: C9pUsageWindow[];
}

/** `task.done` params (`c9watch-agent task done --report`). */
export interface C9pTaskDoneParams {
  /** `C9_AGENT_ID` of the sender. */
  agentId: string;
  report: string;
  /** The sender's clock in ns, as a string. */
  seq: string;
}

/**
 * `task.done` result. In C1a every agent is free, so the call fails with
 * `no_task` instead.
 */
export interface C9pTaskDoneResult {
  taskId: string;
}

/**
 * `detect.recheck`, `session.stop` and `session.rename` result. The call
 * ran one detection tick before it answered: its `session.view` and
 * `session.gone` events are at or before `cursor`.
 */
export interface C9pTickResult {
  /** The detection backend after the tick: `cli` or `legacy`. */
  backend: string;
  cursor: string;
}

/** `events.unsubscribe` params: the `id` of the `events.subscribe` request. */
export interface C9pUnsubscribeParams {
  sub: string;
}

/** `events.unsubscribe` result. No event frame of the stream follows it. */
export interface C9pUnsubscribeResult {
  /** `false` when the connection held no stream with that `sub`. */
  ended: boolean;
}

/** `usage.subscriptions` params. There are none yet. */
export type C9pUsageSubscriptionsParams = Record<string, unknown>;

/**
 * `usage.subscriptions` result: one snapshot per provider plan. The
 * engine reads the providers at most once a minute.
 */
export interface C9pUsageSubscriptionsResult {
  usage: C9pSubscriptionUsage[];
}

export interface C9pUsageWindow {
  label: string;
  resetsAt: number | null;
  usedPercent: number;
  /** Full window length, so the UI can show how far into the window `now` is. */
  windowSeconds: number | null;
}

/**
 * What a session needs from the user. Tool arguments are never included:
 * only the tool *name* leaves the backend.
 */
export type C9pWaitingFor = {
  kind: 'approval';
  tool: string;
} | {
  kind: 'question';
} | {
  kind: 'attention';
} | {
  kind: 'input';
};

/** The frame types on the engine socket. */
export interface C9pFrames {
  event: C9pEventFrame;
  progress: C9pProgressFrame;
  request: C9pRequest;
  response: C9pResponse;
}

/** Each method's params and result (and event frames, for a subscription). */
export interface C9pMethods {
  'agent.create': {
    params: C9pAgentCreateParams;
    result: C9pAgentCreateResult;
  };
  'agent.handoff': {
    params: C9pHandoffParams;
    result: C9pHandoffResult;
  };
  'agent.list': {
    params: C9pAgentListParams;
    result: C9pAgentListResult;
  };
  'agent.retire': {
    params: C9pAgentRetireParams;
    result: C9pAgentRetireResult;
  };
  'auth.can': {
    params: C9pAuthCanParams;
    result: C9pAuthCanResult;
  };
  'auth.rules': {
    params: C9pPingParams;
    result: C9pAuthRulesResult;
  };
  'conversation.get': {
    params: C9pConversationGetParams;
    progress: C9pProgressFrame;
    result: C9pConversationGetResult;
  };
  'cost.get': {
    params: C9pCostGetParams;
    result: C9pCostData;
  };
  'detect.recheck': {
    params: C9pDetectRecheckParams;
    result: C9pTickResult;
  };
  'diag.detection': {
    params: C9pDiagDetectionParams;
    result: C9pDetectionDiagnostics;
  };
  'events.subscribe': {
    events: C9pEventFrame;
    params: C9pSubscribeParams;
    result: C9pSubscribeResult;
  };
  'events.unsubscribe': {
    params: C9pUnsubscribeParams;
    result: C9pUnsubscribeResult;
  };
  hello: {
    params: C9pHelloParams;
    result: C9pHelloResult;
  };
  'history.list': {
    params: C9pHistoryListParams;
    result: C9pHistoryListResult;
  };
  'history.search': {
    params: C9pHistorySearchParams;
    result: C9pHistorySearchResult;
  };
  'hook.notification': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'hook.permission_denied': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'hook.permission_request': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'hook.post_tool_use': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'hook.session_start': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'hook.stop': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'hook.user_prompt_submit': {
    params: C9pHookParams;
    result: C9pHookResult;
  };
  'mail.pause': {
    params: C9pMailAgentParams;
    result: C9pMailControlResult;
  };
  'mail.resume': {
    params: C9pMailAgentParams;
    result: C9pMailControlResult;
  };
  'memory.list': {
    params: C9pMemoryListParams;
    result: C9pMemoryListResult;
  };
  'msg.cancel': {
    params: C9pMsgIdParams;
    result: C9pMailControlResult;
  };
  'msg.list': {
    params: C9pMsgListParams;
    result: C9pMsgListResult;
  };
  'msg.read': {
    params: C9pMsgIdParams;
    result: C9pMsgReadResult;
  };
  'msg.send': {
    params: C9pMsgSendParams;
    result: C9pMsgSendResult;
  };
  ping: {
    params: C9pPingParams;
    result: C9pPingResult;
  };
  'provider.opencode.connect': {
    params: C9pOpencodeConnectParams;
    result: C9pOpencodeStatus;
  };
  'provider.opencode.status': {
    params: C9pOpencodeStatusParams;
    result: C9pOpencodeStatus;
  };
  'session.away': {
    params: C9pSessionAwayParams;
    result: C9pSessionAwayResult;
  };
  'session.list': {
    params: C9pSessionListParams;
    result: C9pSessionListResult;
  };
  'session.rename': {
    params: C9pSessionRenameParams;
    result: C9pTickResult;
  };
  'session.stop': {
    params: C9pSessionStopParams;
    result: C9pTickResult;
  };
  'session.tasks': {
    params: C9pSessionTasksParams;
    result: C9pSessionTasksResult;
  };
  'session.views': {
    params: C9pSessionViewsParams;
    result: C9pSessionViewsResult;
  };
  'snapshot.get': {
    params: C9pSnapshotParams;
    result: C9pSnapshotResult;
  };
  'subagent.list': {
    params: C9pSubagentListParams;
    result: C9pSubagentListResult;
  };
  'subagent.transcript': {
    params: C9pSubagentTranscriptParams;
    result: C9pSubagentTranscript;
  };
  'task.done': {
    params: C9pTaskDoneParams;
    result: C9pTaskDoneResult;
  };
  'usage.subscriptions': {
    params: C9pUsageSubscriptionsParams;
    result: C9pUsageSubscriptionsResult;
  };
}

export type C9pMethod = keyof C9pMethods;

/** Each event topic's `data`. */
export interface C9pTopics {
  'agent.attention': {
    data: C9pAgentAttentionEvent;
  };
  'agent.failed': {
    data: C9pAgentFailedEvent;
  };
  'agent.gone': {
    data: C9pAgentGoneEvent;
  };
  'agent.turn_end': {
    data: C9pAgentTurnEndEvent;
  };
  'agent.upsert': {
    data: C9pAgentRow;
  };
  'diag.detection': {
    data: C9pDetectionDiagnostics;
  };
  'legacy.inbox': {
    data: C9pLegacyInboxEvent;
  };
  'msg.state': {
    data: C9pMsgStateEvent;
  };
  'notification.needs_attention': {
    data: C9pNotificationEvent;
  };
  'notification.waiting_for_input': {
    data: C9pNotificationEvent;
  };
  'session.gone': {
    data: C9pSessionGoneEvent;
  };
  'session.view': {
    data: C9pSessionView;
  };
}

export type C9pTopic = keyof C9pTopics;
